      }
    }
    expect(() => createEveryScheduleRecord(ScheduleId('schedule-every'), ' ', 300, start))
      .toThrow(ScheduleInputError)
    expect(() => createEveryScheduleRecord(ScheduleId('schedule-every'), 'x', 300, Number.NaN))
      .toThrow(ScheduleInputError)
    for (const now of [
